inline const SDI *GetSDI(const void *buf) {
  return ::flatbuffers::GetRoot<SDI>(buf);
}

inline const SDI *GetSizePrefixedSDI(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<SDI>(buf);
}

inline const char *SDIIdentifier() {
  return "$SDI";
}

inline bool SDIBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SDIIdentifier());
}

inline bool SizePrefixedSDIBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SDIIdentifier(), true);
}

template <bool B = false>
inline bool VerifySDIBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<SDI>(SDIIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedSDIBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<SDI>(SDIIdentifier());
}

inline void FinishSDIBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SDI> root) {
  fbb.Finish(root, SDIIdentifier());
}

inline void FinishSizePrefixedSDIBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SDI> root) {
  fbb.FinishSizePrefixed(root, SDIIdentifier());
}

